import 'dart:convert';

import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';

import '../models/name_model.dart';

/// Names bundled with the app (`assets/data/names.json`), generated by
/// `tools/csv_to_json.dart`.
class NamesSeed {
  const NamesSeed({required this.version, required this.names});

  /// `{"version": 3, "names": [ {...}, ... ]}`
  factory NamesSeed.fromJsonString(String source) {
    final Map<String, dynamic> json =
        jsonDecode(source) as Map<String, dynamic>;
    return NamesSeed(
      version: (json['version'] as num?)?.toInt() ?? 0,
      names: [
        for (final Object? e in json['names'] as List<Object?>)
          NameModel.fromJson(e! as Map<String, dynamic>),
      ],
    );
  }

  final int version;
  final List<NameModel> names;
}

abstract interface class NamesSeedSource {
  Future<NamesSeed> load();
}

class AssetNamesSeedSource implements NamesSeedSource {
  const AssetNamesSeedSource({this.assetPath = defaultPath});

  static const String defaultPath = 'assets/data/names.json';

  final String assetPath;

  @override
  Future<NamesSeed> load() async {
    final String raw = await rootBundle.loadString(assetPath, cache: false);
    // Parse off the UI thread; the file can hold thousands of names.
    return compute(NamesSeed.fromJsonString, raw);
  }
}
